userscript.function:

window.Sepoa = $sObject.Sepoa

headerObj = $sObject.headerObj = new SepoaHeaderToolbarObject({
    parent: headerToolbar,
    height: 50,
    logo: {
        align: "center",
        file: window.CONTEXT_NAME + "/theme/" + Sepoa.common.THEME + "/imgs/logo.png"
    },
    items: [{
            type: "text",
            id: "id",
            text: Sepoa.info.ID + " (" + Sepoa.info.NAME_LOC + ")"
        },
        {
            type: "img",
            id: "logout",
            cursor: "pointer",
            img: window.CONTEXT_NAME + "/theme/" + Sepoa.common.THEME + "/imgs/icon/logout.png"
        }
    ]
});
headerObj.attachEvent("onClick", onHeaderClick)

containerObj = $sObject.containerObj = new SepoaMainContainerObject({
    type: (dhx4.isIPad || dhx4.isIPhone) ? '' : Sepoa.config.get('sepoa.frame.type'),
    parent: mainContainer,
    tabbar: {
        mode: "bottom",
        align: "left",
        close_button: true,
        maxTabCount: Sepoa.config.get('sepoa.frame.maxcount'),
        tabs: [{
            id: "SUMMARY",
            text: Sepoa.cache.text.get("SUMMARY.TITLE"),
            active: true,
            close: false,
            url: window.CONTEXT_NAME + "/Summary/SummaryLayout.sux"
        }]
    },
    layout: {
        pattern: "1C",
        skin: "material",
        contents: true,
        cells: [{
            header: false,
            text: " ",
            id: "a",
            url: window.CONTEXT_NAME + "/Summary/SummaryLayout.sux"
        }]
    }
});

SUX.callEvent('onWindowResize', []);


if (id == "logout") {
    Confirm("<span style='font-size: 1.2em;display: inline-block;text-align: left;'>" + Sepoa.cache.text.get('MAIN.ID') + Sepoa.info.ID + "\\n" +
        Sepoa.cache.text.get('MAIN.USER') + Sepoa.info.NAME_LOC + "</span>",
        function(flag) {
            if (flag) {
                location.href = window.CONTEXT_NAME + "/common/logout_process.jsp";
            } else {
                linkTo('AD_050', '/Admin/UpdateUserInfo/AdminUpdateUserInfoLayout.sux');
            }
        }, undefined, Sepoa.cache.text.get('MAIN.LOG_OUT'), Sepoa.cache.text.get('MAIN.CHANGE_USER_INFO'));
} else if (id == "logo") {
    openContainerUrl("SUMMARY", "/Summary/SummaryLayout.sux");
}


doServiceAjax('sepoa.svc.admin.AD_201', 'CONNECTION', 'getPopupNotice', {}, function(so) {
    if (so.status == 1) {
        var l = so.message.split(',');
        var c = getCookie("sepoa.notice.ignore");
        if (c) {
            c = c.split(',');
            for (var i in c) {
                if (l.indexOf(c[i]) + 1) {
                    l.splice(l.indexOf(c[i]), 1);
                }
            }
        }
        if (l.length > 0) {
            PopupOpenPost(window.CONTEXT_NAME + '/Admin/NoticeView/AdminNoticeViewCarousel.sux', {
                NOTICELIST: l.join(',')
            }, '', 1300, '', Sepoa.cache.text.get('MAIN.NOTICE'), 'common');
        }
    }
});


menuTree = getMenuData(Sepoa.info.MENU_PROFILE_CODE);

menuObj.onGroupClick = function(obj) {
    $(".sepoa_menu_screen").slideUp();
    $(".sepoa_menu_group_li").removeClass("group_active")
    if (!$(obj).next().is(":visible")) {
        $(obj).parent().addClass("group_active")
        $(obj).next().slideDown();
    }
}

menuContainer.innerHTML = "";
menuContainer.classList.add("sepoa_menu")

var ul = menuContainer.appendChild(document.createElement('ul'));
ul.id = 'sepoa_menu_group'

for (var i in menuTree) {
    var groupData = menuTree[i];
    var childNodes = groupData.childs;

    if (groupData.HIDDEN_FLAG == "Y") {
        continue;
    }
    if (childNodes.length <= 0) {
        continue;
    }

    var li = ul.appendChild(document.createElement('li'));
    li.id = "sepoa_menu_group_" + groupData.MENU_ID
    li.classList.add("sepoa_menu_group_li")

    var h3 = li.appendChild(document.createElement('h3'));
    h3.innerHTML = '<div style="' + (groupData.MENU_IMG ? ('background-image:url(\'' + window.CONTEXT_NAME + '/theme/<%=theme%>/leftmenu/icon/' + groupData.MENU_IMG + '\');') : ('')) + '"></div>' + groupData.MENU_NAME + '<div class="group_collapse_icon"></div>';
    h3.onclick = function() {
        menuObj.onGroupClick(this);
    }

    var subUl = li.appendChild(document.createElement('ul'));
    subUl.classList.add("sepoa_menu_screen");

    for (var j in childNodes) {
        var detailData = childNodes[j];
        var screenID = detailData.SCREEN_ID || "";
        var menuID = detailData.MENU_ID || "";
        var url = detailData.URL || "";
        var menuImage = detailData.MENU_IMG || "";

        var li = subUl.appendChild(document.createElement('li'))
        li.id = "sepoa_menu_screen_" + detailData.MENU_ID
        li.classList.add("sepoa_menu_screen_li");
        li.style.display = (detailData.HIDDEN_FLAG == 'Y') ? "none" : ""
        li.innerHTML = detailData.MENU_NAME
        li.screenId = detailData.SCREEN_ID;
        li.url = detailData.URL;
        li.onclick = function() {
            var _id = this.screenId
            var _url = this.url
            var _param = this.param
            var _menuName = this.innerHTML
            callFunction('MAINFRAME', 'openContainerUrl', [_id, _url, _param, _menuName]);
        }
    }
}
